    const blob=rowBlob(r);for(const w of extractKw(blob))uniqPush(kws,w);for(const w of extractPains(blob))uniqPush(pains,w);
    const cs=Number(r.competitor_strength);if(cs>1){strengthSum+=cs;strengthN++;}
  }
  const name=str(g[0].company_name)||str(g[0].profile_name)||('(unnamed) '+cut(str(g[0].offer_text),60));
  const evid=g.length;
  const hasPriced=g.some(r=>str(r.terms)!=='');
  const conf=hasPriced?80:(evid>=2?60:45);
  const avgStrength=strengthN?Math.round(strengthSum/strengthN):0;
  const strengths=[];
  if(hasPriced)strengths.push('явный ценовой якорь ('+terms.join(' / ')+')');
  if(kws.indexOf('оплата за результат')>=0)strengths.push('оплата за результат');
  if(kws.indexOf('без предоплаты')>=0)strengths.push('без предоплаты');
  if(avgStrength>=75)strengths.push('сильное объявление (avg competitor_strength '+avgStrength+')');
  const weaknesses=[];
  if(!hasPriced)weaknesses.push('цена/условия не указаны');
  if(platforms.length===1)weaknesses.push('виден только один канал ('+platforms.join('')+')');
  var __lc=__lin(g);
  competitor_profiles.push({
    competitor_id:'comp_'+hashText(k),
    source_run_ids:__lc.source_run_ids, data_mode:__lc.data_mode, report_eligible:__lc.report_eligible,
    competitor_name:name,
    first_seen_at:dates.length?iso(dates[0]):'',
    last_seen_at:dates.length?iso(dates[dates.length-1]):'',
    platforms:platforms.join(', '),
    source_urls:urls.join(' | '),
    service_types:services.join(', '),
    offers:offers.join(' | '),
    prices_terms:terms.join(' | '),
    semantic_keywords:kws.slice(0,12).join(', '),
    pain_points_targeted:pains.join(', '),
    ad_channels:channels.join(', '),
    observed_strengths:strengths.join('; '),
    observed_weaknesses:weaknesses.join('; '),
    evidence_count:evid,
    source_confidence_score:conf,
    notes:'wf10 v0.3 deterministic; run '+str(cfg.run_id)+'; window '+windowDays+'d; group_key='+cut(k,60)
